async function sleep(ms: number) { return new Promise<void>(r => setTimeout(r, ms)); }
async function sleepTyped(ms: number): Promise<void> { return new Promise<void>(r => setTimeout(r, ms)); }
async function f(n: number) { await sleep(n); return n * 2; }
function other(): Promise<number> { return new Promise<number>(r => setTimeout(() => r(7), 20)); }
async function adopt() { return other(); }
class C { async m() { return sleep(20); } async n(): Promise<void> { return sleepTyped(20); } }
async function main(): Promise<void> {
  const t = Date.now();
  await sleep(40);
  console.log(Date.now() - t >= 35);
  await sleepTyped(40);
  console.log(Date.now() - t >= 75);
  console.log(await Promise.race([f(30), f(5)]));
  console.log(await adopt());
  const c = new C();
  const u = Date.now();
  await c.m();
  await c.n();
  console.log(Date.now() - u >= 35);
}
